@php
    $pageHref = function (?string $url): string {
        if (! $url) {
            return '#';
        }
        if (str_starts_with($url, 'http://') || str_starts_with($url, 'https://') || str_starts_with($url, '/')) {
            return $url;
        }

        return '/'.$url;
    };
@endphp

